In development with Strict Mode on, React deliberately mounts, unmounts and re-mounts components once to expose effects that are not cleaned up properly. Production builds run the effect once. If a double run causes trouble (duplicate requests, double subscriptions), the effect needs a cleanup:
```tsx
useEffect(() => {
  const ctrl = new AbortController();
  fetch(`/api/comments/${id}`, { signal: ctrl.signal })
    .then((r) => r.json())
    .then(setData)
    .catch((e) => { if (e.name !== "AbortError") setError(e); });
  return () => ctrl.abort();
}, [id]);
```

```ts
export function debounce<A extends unknown[]>(
  fn: (...args: A) => void,
  waitMs: number,
): (...args: A) => void {
  let timer: ReturnType<typeof setTimeout> | undefined;
  return (...args: A) => {
    if (timer !== undefined) clearTimeout(timer);
    timer = setTimeout(() => fn(...args), waitMs);
  };
}
```Each call resets the timer, so `fn` runs only after `waitMs` of quiet, with the arguments from the last call.

Return a function with a `cancel` property:
```ts
export function debounce<A extends unknown[]>(fn: (...a: A) => void, waitMs: number) {
  let timer: ReturnType<typeof setTimeout> | undefined;
  const wrapped = (...args: A) => {
    if (timer !== undefined) clearTimeout(timer);
    timer = setTimeout(() => { timer = undefined; fn(...args); }, waitMs);
  };
  wrapped.cancel = () => {
    if (timer !== undefined) clearTimeout(timer);
    timer = undefined;
  };
  return wrapped;
}
```

```ts
it("calls once after the wait", () => {
  jest.useFakeTimers();
  const spy = jest.fn();
  const d = debounce(spy, 200);

  d(1); d(2); d(3);
  jest.advanceTimersByTime(199);
  expect(spy).not.toHaveBeenCalled();

  jest.advanceTimersByTime(1);
  expect(spy).toHaveBeenCalledTimes(1);
  expect(spy).toHaveBeenCalledWith(3);
  jest.useRealTimers();
});
```

