        if r.URL.Path != "/users/42" {
            t.Errorf("unexpected path %s", r.URL.Path)
        }
        w.Header().Set("Content-Type", "application/json")
        io.WriteString(w, `{"id":42,"name":"Ada"}`)
    }))
    defer srv.Close()

    c := NewClient(srv.URL)
    u, err := c.FetchUser(context.Background(), 42)
    if err != nil {
        t.Fatal(err)
    }
    if u.Name != "Ada" {
        t.Fatalf("got %q", u.Name)
    }
